import type { TreeRenderer } from './draw';
import type { TreeLibrary } from './load';

/**
 * Tree stats overlay (spec: trees/Performance.md#counters), shown while the LOD debug view is on
 * (`TreeRenderer.debug`, trees/Lod.md#debug-view): last frame's trees per level and fading, draw calls / triangles
 * / GPU ms of the tree main and shadow passes, the CPU ms of level selection, and what loading the variants cost.
 * Call `update()` every frame; it redraws a few times a second.
 */
export class TreeStatsOverlay {
  readonly el: HTMLDivElement;
  private last = 0;

  constructor(
    parent: HTMLElement,
    private trees: TreeRenderer,
    private library: TreeLibrary,
  ) {
    this.el = document.createElement('div');
    Object.assign(this.el.style, {
      position: 'absolute',
      left: '8px',
      top: '76px',
      padding: '6px 8px',
      background: 'rgba(0,0,0,0.6)',
      color: '#dfc',
      font: '11px/1.35 ui-monospace, Consolas, monospace',
      whiteSpace: 'pre',
      pointerEvents: 'none',
      zIndex: '21',
  commits = 0;

  constructor(
    private world: World,
    private library: TreeLibrary,
    private opts: TreeRendererOptions,
  ) {
    this.group.name = 'trees';
    const q = typeof location !== 'undefined' ? new URLSearchParams(location.search).get('treedebug') : null;
    if (q) this.debugMode = Number(q) || 1;
  }

  /** Debug view mode: 0 off, 1 levels / fades / flicker, 2 lighting only, 3 normals, 4 depth, 5 equal-test misses. */
  get debugMode(): number {
    return treeUniforms.tlDebug.value;
  }

  set debugMode(m: number) {
    treeUniforms.tlDebug.value = Math.max(0, Math.min(5, Math.round(m)));
    setSpritePrepassDebug(treeUniforms.tlDebug.value === 5);
  }

